    hospital_name character varying(255),
    patient_id character varying(50),
    is_active boolean DEFAULT true,
    is_verified boolean DEFAULT false,
    is_approved boolean DEFAULT false,
    approval_status character varying(20) DEFAULT 'pending'::character varying,
    approved_at timestamp with time zone,
    approved_by character varying(50),
    rejected_at timestamp with time zone,
    rejected_by character varying(50),
    admin_privileges jsonb,
    is_admin boolean DEFAULT false,
    preferences jsonb DEFAULT '{"theme": "light", "language": "th", "notifications": true}'::jsonb,
    notification_settings jsonb DEFAULT '{"sms": false, "push": true, "email": true, "messages": true, "promotions": false, "appointments": true, "healthReminders": true}'::jsonb,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    last_login timestamp with time zone,
    login_attempts integer DEFAULT 0,
    locked_until timestamp with time zone,
    CONSTRAINT users_role_check CHECK (((role)::text = ANY ((ARRAY['doctor'::character varying, 'admin'::character varying, 'patient'::character varying])::text[])))
);


ALTER TABLE public.users OWNER TO postgres;

--
-- Name: v_active_appointments; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_active_appointments AS
 SELECT a.id,
    a.patient_id,
    a.doctor_id,
    a.requested_date,
    a.requested_time,
    a.confirmed_date,
    a.confirmed_time,
    a.appointment_type,
    a.appointment_date,
    a.appointment_time,
    a.reason,
    a.status,
    a.urgency_level,
    a.symptoms,
    a.symptom_description,
    a.ai_triage,
    a.notes,
    a.meet_link,
    a.meeting_link,
    a.jitsi_room_name,
    a.invitees,
    a.created_at,
    a.updated_at,
    a.confirmed_at,
    a.completed_at,
    a.cancelled_at,
    a.cancellation_reason,
    p.name AS patient_name,
    p.name_thai AS patient_name_thai,
    d.name AS doctor_name,
    d.name_thai AS doctor_name_thai,
    d.specialty AS doctor_specialty
   FROM ((public.appointments a
     LEFT JOIN public.users p ON (((a.patient_id)::text = (p.id)::text)))
     LEFT JOIN public.users d ON (((a.doctor_id)::text = (d.id)::text)))
  WHERE ((a.status)::text <> ALL ((ARRAY['completed'::character varying, 'cancelled'::character varying])::text[]));


ALTER VIEW public.v_active_appointments OWNER TO postgres;

--
-- Name: v_doctor_summary; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_doctor_summary AS
 SELECT u.id,
    u.name,
    u.name_thai,
    u.email,
    u.specialty,
    u.hospital_name,
    u.is_approved,
    u.approval_status,
    dp.rating,
    dp.total_reviews,
    dp.is_available
   FROM (public.users u
     LEFT JOIN public.doctor_profiles dp ON (((u.id)::text = (dp.doctor_id)::text)))
  WHERE ((u.role)::text = 'doctor'::text);


ALTER VIEW public.v_doctor_summary OWNER TO postgres;

--
-- Name: v_patient_summary; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_patient_summary AS
 SELECT u.id,
    u.name,
    u.name_thai,
    u.email,
    phr.demographics,
    phr.allergies,
    phr.chronic_conditions,
    phr.medications,
    phr.clinical_decision_support
   FROM (public.users u
     LEFT JOIN public.phr ON (((u.id)::text = (phr.patient_id)::text)))
  WHERE ((u.role)::text = 'patient'::text);


ALTER VIEW public.v_patient_summary OWNER TO postgres;

--
-- Name: vital_signs; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.vital_signs (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    patient_id character varying(50),
    blood_pressure_systolic integer,
    blood_pressure_diastolic integer,
    heart_rate integer,
    temperature numeric(4,1),
    respiratory_rate integer,
    oxygen_saturation integer,
    blood_glucose integer,
    blood_glucose_type character varying(20),
    weight numeric(5,1),
    height numeric(5,1),
    bmi numeric(4,1),
    measured_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    source character varying(20) DEFAULT 'patient_input'::character varying,
    notes text
);


ALTER TABLE public.vital_signs OWNER TO postgres;

